import { useRef, useState } from "react";
import { defineMessages, useIntl } from "react-intl";
import type {
  ButtonRenderer as ButtonData,
  CompactInfocardRenderer,
  ExpandableVideoDescriptionBodyRenderer,
  HowThisWasMadeSectionViewModel,
  MediaLockupRenderer,
  StructuredDescriptionVideoLockupRenderer,
  VideoDescriptionHeaderRenderer,
  VideoDescriptionInfocardsSectionRenderer,
  VideoDescriptionTranscriptSectionRenderer,
} from "../../../model/innertube.gen";
import type { Endpoint } from "../../../model/endpoints";
import { getText, type AttributedText, type FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import { FormattedString } from "../../../components/text/FormattedString";
import { AttributedString } from "../../../components/text/AttributedString";
import { EndpointLink } from "../../../components/text/EndpointLink";
import { ImgShadow } from "../../../components/image/Image";
import { ButtonRenderer } from "../../../components/button/ButtonRenderer";
import { ButtonViewModel } from "../../../components/button/ButtonViewModel";
import { Icon } from "../../../components/icon/Icon";
import { Thumbnail, type ThumbnailOverlay } from "../../../components/thumbnail/Thumbnail";
import styles from "./DescriptionParts.module.css";

const messages = defineMessages({
  views: { id: "description.factoid.views", defaultMessage: "Views" },
  date: { id: "description.factoid.date", defaultMessage: "Date" },
  more: { id: "description.body.more", defaultMessage: "Show more" },
  less: { id: "description.body.less", defaultMessage: "Show less" },
  scrollLeft: { id: "description.infocards.left", defaultMessage: "Scroll left" },
  scrollRight: { id: "description.infocards.right", defaultMessage: "Scroll right" },
});

/** The panel's header: title, channel and the views and date factoids. */
export function VideoDescriptionHeader({ data }: { data: VideoDescriptionHeaderRenderer }) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={styles.header}>
      <div className={styles.headerTitle}>
        <FormattedString text={data.title as FormattedText} />
      </div>
      <div className={styles.channelContainer}>
        <EndpointLink endpoint={data.channelNavigationEndpoint as unknown as Endpoint} tabIndex={-1} aria-hidden="true" className={styles.channelThumbnail}>
          <ImgShadow image={data.channelThumbnail} width={48} />
        </EndpointLink>
        <div className={styles.channelInfo}>
          <FormattedString text={data.channel as FormattedText} className={styles.channel} />
        </div>
      </div>
      <div className={styles.factoids}>
        <div className={styles.factoid}>
          <div className={styles.factoidValue}>{getText(data.views as FormattedText)}</div>
          <div className={styles.factoidLabel}>{intl.formatMessage(messages.views)}</div>
        </div>
        <div className={styles.factoid}>
          <div className={styles.factoidValue}>{getText(data.publishDate as FormattedText)}</div>
          <div className={styles.factoidLabel}>{intl.formatMessage(messages.date)}</div>
        </div>
      </div>
    </div>
  );
}

/** The description text in the panel, clamped until expanded. */
export function ExpandableVideoDescriptionBody({ data }: { data: ExpandableVideoDescriptionBodyRenderer }) {
  const intl = useIntl();
  const textRef = useRef<HTMLDivElement>(null);
  const [expanded, setExpanded] = useState(false);
  const [truncated, setTruncated] = useState(false);
  useResizeObserver(textRef, () => {
    const el = textRef.current;
    if (el && !expanded) setTruncated(el.scrollHeight > el.clientHeight + 1);
  });
  const more = getText(data.showMoreText as FormattedText) || intl.formatMessage(messages.more);
  const less = getText(data.showLessText as FormattedText) || intl.formatMessage(messages.less);
  return (
    <div className={styles.body}>
      <div ref={textRef} className={expanded ? styles.bodyText : styles.bodyTextClamped}>
        <AttributedString text={data.attributedDescriptionBodyText as AttributedText} />
      </div>
      {(expanded || truncated) && (
        <button type="button" className={styles.textButton} aria-expanded={expanded} onClick={() => setExpanded(!expanded)}>
          {expanded ? less : more}
        </button>
      )}
    </div>
  );
}

/** The transcript section: a title, a hint and the button that opens the transcript. */
export function TranscriptSection({ data }: { data: VideoDescriptionTranscriptSectionRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const button = (data.primaryButton as { buttonRenderer?: ButtonData } | undefined)?.buttonRenderer;
  return (
    <div ref={ref} className={styles.transcript}>
      <div className={styles.sectionHeader}>
        <div className={styles.sectionTitle}>{getText(data.sectionTitle as FormattedText)}</div>
      </div>
      <p className={styles.subHeader}>{getText(data.subHeaderText as FormattedText)}</p>
      {button && (
        <div className={styles.buttonContainer}>
          <ButtonRenderer data={button} />
        </div>
      )}
    </div>
  );
}

/** A video card of an infocard. */
function VideoLockupCard({ lockup }: { lockup: StructuredDescriptionVideoLockupRenderer }) {
  const endpoint = lockup.disableNavigationEndpoint ? undefined : (lockup.navigationEndpoint as Endpoint);
  return (
    <>
      <Thumbnail thumbnail={lockup.thumbnail} endpoint={endpoint} overlays={lockup.thumbnailOverlays as ThumbnailOverlay[]} width={lockup.thumbnailWidth ?? 112} className={styles.infocardThumbnail} />
      <div className={styles.infocardDetails}>
        <EndpointLink endpoint={endpoint} className={styles.infocardTitle}>
          {getText(lockup.title as FormattedText)}
        </EndpointLink>
        <div className={styles.infocardByline}>{getText(lockup.shortBylineText as FormattedText)}</div>
        <div className={styles.infocardByline}>{getText(lockup.metadataDetails as FormattedText)}</div>
      </div>
    </>
  );
}

/** A link card of an infocard: an image, a title and the site, which opens in a new window if the link says so. */
function MediaLockup({ data }: { data: MediaLockupRenderer }) {
  const endpoint = data.endpoint as unknown as Endpoint;
  const newWindow = data.endpoint.urlEndpoint?.target === "TARGET_NEW_WINDOW";
  const title = getText(data.title);
  const width = data.uiTweaks?.thumbnailWidth || 112;
  return (
    <EndpointLink endpoint={endpoint} className={styles.mediaLockup} target={newWindow ? "_blank" : undefined} rel={newWindow ? "noopener" : undefined}>
      <span className={styles.mediaThumbnail} style={{ width }}>
        <ImgShadow image={data.thumbnailDetails} width={width} />
      </span>
      <span className={styles.infocardDetails}>
        <span className={styles.infocardTitle} style={{ WebkitLineClamp: data.maxLinesTitle || 2 }}>
          {title}
        </span>
        <span className={styles.mediaSubtitle}>
          <span className={styles.infocardByline}>{getText(data.subtitle)}</span>
          {newWindow && data.enableSubtitleLaunchIcon && <Icon icon="OPEN_IN_NEW" size={12} />}
        </span>
      </span>
    </EndpointLink>
  );
}

/** A card in the infocards section: a video or an external link. */
function CompactInfocard({ data }: { data: CompactInfocardRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const { structuredDescriptionVideoLockupRenderer: lockup, mediaLockupRenderer: media } = data.content;
  if (!lockup && !media) return null;
  return (
    <div ref={ref} className={styles.infocard}>
      {lockup ? <VideoLockupCard lockup={lockup} /> : media && <MediaLockup data={media} />}
    </div>
  );
}

/** The channel's links and featured videos, in a row that scrolls with arrows. */
export function InfocardsSection({ data }: { data: VideoDescriptionInfocardsSectionRenderer }) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  const scrollerRef = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const [arrows, setArrows] = useState({ left: false, right: false });
  const updateArrows = () => {
    const scroller = scrollerRef.current;
    if (!scroller) return;
    const overflow = scroller.scrollWidth - scroller.clientWidth;
    const left = scroller.scrollLeft > 0;
    const right = overflow - scroller.scrollLeft > 1;
    setArrows((a) => (a.left === left && a.right === right ? a : { left, right }));
  };
  useResizeObserver(scrollerRef, updateArrows);
  const buttons = [data.creatorVideosButton.buttonRenderer, data.creatorAboutButton.buttonRenderer];
  const customUrlButtons = data.creatorCustomUrlButtons ?? [];
  const scroll = (direction: 1 | -1) => {
    const scroller = scrollerRef.current;
    if (scroller) scroller.scrollLeft += direction * scroller.clientWidth;
  };
  return (
    <div ref={ref} className={styles.infocards}>
      <EndpointLink endpoint={data.channelEndpoint as unknown as Endpoint} className={styles.infocardsHeader}>
        <ImgShadow image={data.channelAvatar} width={56} className={styles.channelAvatar} />
        <div className={styles.infocardsHeaderText}>
          <h3 className={styles.sectionTitle}>{getText(data.sectionTitle)}</h3>
          <div className={styles.subtitle}>{getText(data.sectionSubtitle)}</div>
        </div>
      </EndpointLink>
      <div className={styles.socialLinks}>
        {arrows.left && (
          <button type="button" className={styles.arrowLeft} aria-label={intl.formatMessage(messages.scrollLeft)} onClick={() => scroll(-1)}>
            <Icon icon="CHEVRON_LEFT" />
          </button>
        )}
        <div ref={scrollerRef} className={styles.scrollContainer} onScroll={updateArrows}>
          <div className={styles.links}>
            {buttons.map((button, i) => (
              <ButtonRenderer key={button.trackingParams ?? i} data={button} />
            ))}
            {customUrlButtons.map((button, i) => (
              <ButtonViewModel key={i} data={button.buttonViewModel} />
            ))}
          </div>
        </div>
        {arrows.right && (
          <button type="button" className={styles.arrowRight} aria-label={intl.formatMessage(messages.scrollRight)} onClick={() => scroll(1)}>
            <Icon icon="CHEVRON_RIGHT" />
          </button>
        )}
      </div>
      <div className={styles.infocardList}>
        {(data.infocards ?? []).map((card, i) => (
          <CompactInfocard key={card.compactInfocardRenderer.trackingParams ?? i} data={card.compactInfocardRenderer} />
        ))}
      </div>
    </div>
  );
}

/** How the video was made: altered or synthetic content, with an optional attribution. */
export function HowThisWasMadeSection({ data }: { data: HowThisWasMadeSectionViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const attribution = data.attributionText as AttributedText | undefined;
  return (
    <div ref={ref} className={data.shouldRemoveBottomPadding ? styles.howThisWasMadeFlush : styles.howThisWasMade}>
      <h3 className={styles.sectionTitle}>
        <AttributedString text={data.sectionTitle as AttributedText} />
      </h3>
      <div className={styles.bodyHeader}>
        <AttributedString text={data.bodyHeader as AttributedText} />
      </div>
      <div className={styles.subtitle}>
        <AttributedString text={data.bodyText as AttributedText} />
      </div>
      {attribution?.content && (
        <div className={styles.subtitle}>
          <AttributedString text={attribution} />
        </div>
      )}
    </div>
  );
}
