import { defineMessages, useIntl } from "react-intl";
import type { ButtonRenderer as ButtonData, DownloadButtonRenderer } from "../../../model/innertube.gen";
import { ButtonRenderer } from "../../../components/button/ButtonRenderer";

const messages = defineMessages({
  download: { id: "watch.download", defaultMessage: "Download" },
});

/** The download action: a tonal button with the download icon. */
export function DownloadButton({ data }: { data: DownloadButtonRenderer }) {
  const intl = useIntl();
  const text = intl.formatMessage(messages.download);
  const button = {
    style: data.style,
    size: data.size,
    text: { simpleText: text },
    icon: { iconType: "DOWNLOAD" },
    accessibility: { label: text },
    trackingParams: data.trackingParams,
    command: data.command,
  } as unknown as ButtonData;
  return <ButtonRenderer data={button} />;
}
