import { infiniteQueryOptions } from "@tanstack/react-query";
import { continuation } from "../../api/innertube";
import { parseResponse } from "../../model/response";
import type { CommentsAppendResponse, CommentsReloadResponse } from "../../model/innertube.gen";
import { commentsPageFromAppend, commentsPageFromReload, type CommentsPage } from "../../model/comments";
import { continuationParam, measured, type PageParam } from "../../api/requests";
import { NEXT_API } from "../watch/queries";

type CommentsParam = (PageParam & { reload?: boolean }) | null;

/**
 * The comment section, loaded when it comes into view: the first page
 * reloads the section from `start` (the section's continuation, or a sort
 * option's), later pages append.
 */
export function commentsQueryOptions(videoId: string, start: PageParam | undefined) {
  return infiniteQueryOptions({
    queryKey: ["comments", videoId, start?.token ?? null],
    initialPageParam: (start ? { ...start, reload: true } : null) as CommentsParam,
    queryFn: ({ pageParam }): Promise<CommentsPage> => {
      if (!pageParam) return Promise.resolve({ header: null, threads: [], continuation: null });
      return measured("watch", "continuation", async () => {
        if (pageParam.reload) {
          return commentsPageFromReload(parseResponse<CommentsReloadResponse>(await continuation("comments-reload", NEXT_API, pageParam.token, pageParam.clickTrackingParams)));
        }
        return commentsPageFromAppend(parseResponse<CommentsAppendResponse>(await continuation("comments-append", NEXT_API, pageParam.token, pageParam.clickTrackingParams)));
      });
    },
    getNextPageParam: (last): CommentsParam | undefined => continuationParam(last.continuation),
  });
}
