import clsx from "clsx";
import { useRef, useState } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { AttributedText } from "../../model/text";
import { AttributedString } from "../../components/text/AttributedString";
import { useResizeObserver } from "../../hooks/useResizeObserver";
import styles from "./CommentExpander.module.css";

const messages = defineMessages({
  more: { id: "comment.readMore", defaultMessage: "Read more" },
  less: { id: "comment.showLess", defaultMessage: "Show less" },
});

/** The height of a collapsed comment, about four lines. */
const COLLAPSED_HEIGHT = 80;

export interface CommentExpanderProps {
  text: AttributedText | undefined;
  /** The paid comment chip (Super Thanks) above the text. */
  chip?: string;
  expandText?: string;
  collapseText?: string;
}

/** A comment's text, cut to four lines with "Read more" when it is longer. */
export function CommentExpander({ text, chip, expandText, collapseText }: CommentExpanderProps) {
  const intl = useIntl();
  const contentRef = useRef<HTMLDivElement>(null);
  const [expanded, setExpanded] = useState(false);
  const [canToggle, setCanToggle] = useState(false);
  // Whether the text is longer than the collapsed height changes only
  // together with the content's size, so size changes keep this current.
  useResizeObserver(contentRef, () => {
    const content = contentRef.current;
    if (content) setCanToggle(content.scrollHeight > COLLAPSED_HEIGHT);
  });
  return (
    <div className={styles.expander}>
      <div ref={contentRef} className={clsx(styles.content, !expanded && styles.collapsed)}>
        {chip && <span className={styles.chip}>{chip}</span>}
        <AttributedString text={text} className={styles.text} />
      </div>
      {canToggle && (
        <button type="button" className={styles.toggle} aria-expanded={expanded} onClick={() => setExpanded(!expanded)}>
          {expanded ? collapseText?.trim() || intl.formatMessage(messages.less) : expandText?.trim() || intl.formatMessage(messages.more)}
        </button>
      )}
    </div>
  );
}
