import { useId } from "react";
import type { VideoPrimaryInfoRenderer } from "../../../model/innertube.gen";
import { getText, getRuns, type FormattedText } from "../../../model/text";
import { flags } from "../../../flags";
import { FormattedString } from "../../../components/text/FormattedString";
import { AnimatedRollingNumber } from "../../../components/text/AnimatedRollingNumber";
import { Tooltip } from "../../../components/feedback/Tooltip";
import styles from "./WatchInfoText.module.css";

/** Splits "1,234 views" into the number, which rolls when it changes, and the rest. */
export function splitNumber(text: FormattedText | null | undefined): { number: string; suffix: string } {
  const s = getText(text);
  const m = /^([\d.,\s]+)(.*)$/.exec(s);
  return m ? { number: m[1].trim(), suffix: m[2] } : { number: "", suffix: s };
}

function Count({ text, animate }: { text: FormattedText | null | undefined; animate: boolean }) {
  if (!animate) return <FormattedString text={text} />;
  const { number, suffix } = splitNumber(text);
  return (
    <>
      {number && <AnimatedRollingNumber text={number} />}
      <FormattedString text={{ simpleText: suffix }} />
    </>
  );
}

/** The line above the description: hashtags, view count, date and info. */
export function WatchInfoText({ data }: { data: VideoPrimaryInfoRenderer }) {
  const tooltipId = useId();
  const animate = !flags.bool("disable_watch_info_text_rolling_numbers");
  const views = data.viewCount?.videoViewCountRenderer as { viewCount?: FormattedText; shortViewCount?: FormattedText } | undefined;
  const viewCount = views?.viewCount ?? views?.shortViewCount;
  const superTitle = data.superTitleLink as FormattedText | undefined;
  const info = { runs: getRuns(superTitle).map((run) => ({ text: ` ${run.text}` })) };
  const tooltip = [getText(views?.viewCount), getText(data.dateText as FormattedText)].filter(Boolean).join(" • ");
  return (
    <div className={styles.infoText}>
      <div className={styles.container} aria-describedby={tooltip ? tooltipId : undefined}>
        {superTitle && <FormattedString text={superTitle} className={styles.superTitle} />}
        <div className={styles.count}>
          <Count text={viewCount} animate={animate} />
        </div>
        <div className={styles.count}>
          <Count text={data.dateText as FormattedText} animate={animate} />
        </div>
        <FormattedString text={info} className={styles.info} />
      </div>
      <Tooltip text={tooltip} id={tooltipId} />
    </div>
  );
}
