import { useRef } from "react";
import type { ProductListHeaderRenderer, ProductListItemRenderer, ProductListRenderer } from "../../../model/innertube.gen";
import type { Endpoint } from "../../../model/endpoints";
import type { FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { FormattedString } from "../../../components/text/FormattedString";
import { EndpointLink } from "../../../components/text/EndpointLink";
import { Image } from "../../../components/image/Image";
import { ButtonRenderer } from "../../../components/button/ButtonRenderer";
import styles from "./ProductList.module.css";

function ProductListHeader({ data }: { data: ProductListHeaderRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={data.suppressPaddingDisclaimer ? styles.headerFlush : styles.header}>
      <FormattedString text={data.title as FormattedText} className={styles.disclaimer} />
    </div>
  );
}

/** A product: image, title, merchant and price, and a button to the store. */
function ProductListItem({ data }: { data: ProductListItemRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const price = data.priceReplacementText ?? data.price;
  return (
    <div ref={ref} className={styles.item}>
      <EndpointLink endpoint={data.onClickCommand as Endpoint | undefined} className={styles.link} aria-label={data.accessibilityTitle} rel={data.stayInApp ? undefined : "nofollow"}>
        <Image image={data.thumbnail} width={72} fit="contain" className={styles.thumbnail} />
        <div className={styles.info}>
          <h4 className={styles.title}>{data.title.simpleText}</h4>
          <div className={styles.merchant}>{data.merchantName}</div>
          {price && <div className={data.priceReplacementText ? styles.priceReplacement : styles.price}>{price}</div>}
        </div>
      </EndpointLink>
      <div className={styles.view}>
        <ButtonRenderer data={{ ...data.viewButton.buttonRenderer, size: "SIZE_SMALL" }} />
      </div>
    </div>
  );
}

/** The products of a shopping panel, under a disclaimer header. */
export function ProductList({ data }: { data: ProductListRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={styles.list}>
      {data.contents.map((item, i) =>
        item.productListHeaderRenderer ? (
          <ProductListHeader key={item.productListHeaderRenderer.trackingParams ?? i} data={item.productListHeaderRenderer} />
        ) : item.productListItemRenderer ? (
          <ProductListItem key={item.productListItemRenderer.trackingParams ?? i} data={item.productListItemRenderer} />
        ) : null,
      )}
    </div>
  );
}
