import clsx from "clsx";
import { useRef, useState } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { MerchandiseItemRenderer, MerchandiseShelfRenderer } from "../../../model/innertube.gen";
import type { Endpoint } from "../../../model/endpoints";
import type { FormattedText } from "../../../model/text";
import { useImpression, logClick } from "../../../logging/impressions";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import { useRunCommand } from "../../../commands/useRunCommand";
import { FormattedString } from "../../../components/text/FormattedString";
import { Image } from "../../../components/image/Image";
import { Icon } from "../../../components/icon/Icon";
import styles from "./MerchandiseShelf.module.css";

const messages = defineMessages({
  scrollLeft: { id: "merchandise.left", defaultMessage: "Previous products" },
  scrollRight: { id: "merchandise.right", defaultMessage: "Next products" },
});

/** The shelf width from which a shelf of several items shows large items. */
const LARGE_ITEM_MIN_WIDTH = 740;

type ItemStyle = "small" | "large" | "cta" | "link" | "compact";

function itemStyleFor(data: MerchandiseShelfRenderer, width: number): ItemStyle {
  switch (data.shelfType as string) {
    case "MERCHANDISE_SHELF_TYPE_PRODUCT_LINK":
    case "MERCHANDISE_SHELF_TYPE_LINK_MERCH_SHELF":
      return "link";
    case "MERCHANDISE_SHELF_TYPE_COMPACT":
      return "compact";
    default:
      if (data.items.length === 1) return "cta";
      return width >= LARGE_ITEM_MIN_WIDTH ? "large" : "small";
  }
}

function MerchandiseItem({ data, itemStyle }: { data: MerchandiseItemRenderer; itemStyle: ItemStyle }) {
  const ref = useRef<HTMLAnchorElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const label = data.accessibilityTitle || [data.title, data.price, data.additionalFeesText, data.vendorName].filter(Boolean).join(", ");
  const showIcon = data.showOpenInNewIcon !== false;
  const price = data.priceReplacementText ?? data.price;
  return (
    <a
      ref={ref}
      className={clsx(styles.item, styles[itemStyle])}
      href={(data.buttonCommand as Endpoint).commandMetadata?.webCommandMetadata?.url}
      aria-label={label}
      onClick={(e) => {
        e.preventDefault();
        logClick(data);
        runCommand(data.buttonCommand as Endpoint);
      }}
    >
      <Image image={data.thumbnail} width={90} fit="contain" className={styles.image} />
      <div className={styles.info}>
        {itemStyle !== "small" && (
          <div className={styles.titleRow}>
            <div className={styles.title}>{data.title}</div>
            {showIcon && <Icon icon="OPEN_IN_NEW" size={15} className={styles.titleIcon} />}
          </div>
        )}
        {price && itemStyle !== "compact" && (
          <div className={styles.priceRow}>
            <div className={styles.price}>{price}</div>
            {data.additionalFeesText && !data.priceReplacementText && <div className={styles.fees}>{data.additionalFeesText}</div>}
          </div>
        )}
        {(itemStyle === "small" || itemStyle === "large") && (
          <div className={styles.merchant}>
            <span className={styles.merchantText}>{data.vendorName}</span>
            {showIcon && <Icon icon="OPEN_IN_NEW" size={15} />}
          </div>
        )}
        {itemStyle === "cta" && <div className={styles.description}>{data.description}</div>}
      </div>
      {itemStyle === "cta" && (
        <div className={styles.buttonWrapper} aria-label={data.buttonAccessibilityText}>
          <div className={styles.button}>{data.buttonText}</div>
          <div className={styles.merchant}>{data.vendorName}</div>
        </div>
      )}
    </a>
  );
}

/**
 * The creator's merchandise in the description: a title and a row of
 * products that pages with arrows. The item layout depends on the shelf
 * type and, for the default type, on the shelf's width.
 */
export function MerchandiseShelf({ data }: { data: MerchandiseShelfRenderer }) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  const scrollerRef = useRef<HTMLDivElement>(null);
  const itemsRef = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const [itemStyle, setItemStyle] = useState<ItemStyle>(() => itemStyleFor(data, 0));
  const [offset, setOffset] = useState(0);
  const [maxOffset, setMaxOffset] = useState(0);
  useResizeObserver(scrollerRef, () => {
    const scroller = scrollerRef.current;
    const items = itemsRef.current;
    if (!scroller || !items || scroller.clientWidth === 0) return;
    const width = scroller.clientWidth;
    const max = Math.max(0, items.scrollWidth - width);
    setMaxOffset(max);
    setOffset((o) => Math.min(o, max));
    setItemStyle(itemStyleFor(data, width));
  });
  const page = (direction: 1 | -1) => {
    const width = scrollerRef.current?.clientWidth ?? 0;
    setOffset((o) => Math.max(0, Math.min(maxOffset, o + direction * width)));
  };
  return (
    <div ref={ref} className={styles.shelf}>
      <div className={styles.banner}>
        <FormattedString text={data.titleFormatted as FormattedText} className={styles.shelfTitle} as="h3" />
      </div>
      <div className={styles.itemList}>
        {offset > 0 && (
          <button type="button" className={clsx(styles.arrow, styles.left)} aria-label={intl.formatMessage(messages.scrollLeft)} onClick={() => page(-1)}>
            <Icon icon="CHEVRON_LEFT" />
          </button>
        )}
        <div ref={scrollerRef} className={styles.scroller}>
          <div ref={itemsRef} className={styles.items} style={{ transform: offset ? `translateX(${-offset}px)` : undefined }}>
            {data.items.map((item, i) => (
              <MerchandiseItem key={item.merchandiseItemRenderer.trackingParams ?? i} data={item.merchandiseItemRenderer} itemStyle={itemStyle} />
            ))}
          </div>
        </div>
        {offset < maxOffset && (
          <button type="button" className={clsx(styles.arrow, styles.right)} aria-label={intl.formatMessage(messages.scrollRight)} onClick={() => page(1)}>
            <Icon icon="CHEVRON_RIGHT" />
          </button>
        )}
      </div>
    </div>
  );
}
