import { useRef } from "react";
import type { VideoOwnerRenderer } from "../../../model/innertube.gen";
import type { Endpoint } from "../../../model/endpoints";
import type { FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { EndpointLink } from "../../../components/text/EndpointLink";
import { FormattedString } from "../../../components/text/FormattedString";
import { ImgShadow } from "../../../components/image/Image";
import { ChannelName } from "../../../components/channel/ChannelName";
import styles from "./VideoOwner.module.css";

/** The channel of the video: avatar, name with badges, and subscriber count. */
export function VideoOwner({ data }: { data: VideoOwnerRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const endpoint = data.navigationEndpoint as Endpoint;
  return (
    <div ref={ref} className={styles.owner} data-renderer="videoOwnerRenderer">
      <EndpointLink endpoint={endpoint} tabIndex={-1} aria-hidden="true" className={styles.avatarLink}>
        <ImgShadow image={data.thumbnail} width={40} className={styles.avatar} />
      </EndpointLink>
      <div className={styles.uploadInfo}>
        <ChannelName name={data.title as FormattedText} badges={data.badges} className={styles.channelName} />
        <FormattedString text={data.subscriberCountText as FormattedText} className={styles.subCount} />
      </div>
    </div>
  );
}
