import styles from "./AnimatedRollingNumber.module.css";

/**
 * A number whose digits roll to their new value when it changes. Each digit
 * is its own element, keyed by its place from the right, so that a digit
 * keeps its element, and its transition, when the number grows.
 */
export function AnimatedRollingNumber({ text }: { text: string }) {
  const chars = [...text];
  return (
    <span className={styles.number}>
      <span className={styles.label}>{text}</span>
      {chars.map((ch, i) => (
        <span key={chars.length - i} className={ch >= "0" && ch <= "9" ? styles.digit : styles.separator} aria-hidden="true">
          {ch}
        </span>
      ))}
    </span>
  );
}
